const coursesBySubject = computed(() => {
  const map = {};
  for (const c of courses.value) {
    const s = c.subject || '';
    if (!s) continue;
    map[s] = (map[s] || 0) + 1;
  }
  return Object.entries(map).map(([subject, count]) => ({
    subject,
    label: getSubjectLabel(subject),
    count
  })).sort((a, b) => b.count - a.count);
});

